"""Procedural foil textures (provenance: generated by this script, no external source).
public/foil/prizm.webp   - seamless prizm refractor plate for holo cards (used with color-dodge)
public/foil/chrome.webp  - chrome frame for holo card borders
public/foil/wrapper.webp - crinkled metallised pack-wrapper film
"""
import numpy as np
from pathlib import Path
from PIL import Image, ImageFilter

OUT = Path(__file__).resolve().parent.parent / "public" / "foil"
OUT.mkdir(parents=True, exist_ok=True)
rng = np.random.default_rng(26)
N = 768

def hsv2rgb(h, s, v):
    i = np.floor(h * 6).astype(int) % 6
    f = h * 6 - np.floor(h * 6)
    p, q, t = v * (1 - s), v * (1 - f * s), v * (1 - (1 - f) * s)
    r = np.choose(i, [v, q, p, p, t, v]); g = np.choose(i, [t, v, v, q, p, p]); b = np.choose(i, [p, p, t, v, v, q])
    return np.stack([r, g, b], -1)

def tile_noise(n, scale, octaves=4):
    acc = np.zeros((n, n))
    for o in range(octaves):
        k = scale * 2 ** o
        g = rng.random((k, k))
        im = Image.fromarray((g * 255).astype(np.uint8)).resize((n, n), Image.BICUBIC)
        # make seamless by sampling a periodic grid
        acc += np.asarray(im, float) / 255 / 2 ** o
    return acc / acc.max()

y, x = np.mgrid[0:N, 0:N] / N
# Prizm: diagonal rainbow bands + facet shards (Voronoi-like cells) shifting the hue.
cells = 38
pts = rng.random((cells, 2))
d = np.full((N, N), 9.0); idx = np.zeros((N, N), int)
for k, (px, py) in enumerate(pts):
    for ox in (-1, 0, 1):
        for oy in (-1, 0, 1):
            dd = (x - px - ox) ** 2 + (y - py - oy) ** 2
            m = dd < d; d[m] = dd[m]; idx[m] = k
shift = rng.random(cells)[idx]
hue = ((x + y) * 3 + shift * 0.35) % 1.0
spark = (rng.random((N, N)) > 0.997).astype(float)
spark = np.asarray(Image.fromarray((spark * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(0.8)), float) / 255
v = 0.62 + 0.25 * np.sin((x - y) * np.pi * 14) ** 2 + spark * 1.6
rgb = hsv2rgb(hue, np.full_like(hue, 0.78), np.clip(v, 0, 1))
Image.fromarray((np.clip(rgb, 0, 1) * 255).astype(np.uint8)).save(OUT / "prizm.webp", quality=82)

# Chrome: cool brushed metal with faint iridescent drift.
brush = np.asarray(Image.fromarray((rng.random((N, N)) * 255).astype(np.uint8)).filter(ImageFilter.BoxBlur(0)).resize((N, N)), float)
brush = np.asarray(Image.fromarray(brush.astype(np.uint8)).filter(ImageFilter.GaussianBlur(radius=0)).transform((N, N), Image.AFFINE, (1, 0, 0, 0, 0.02, 0)), float) / 255
band = 0.55 + 0.35 * np.cos((x * 0.6 + y) * np.pi * 3) ** 2
lum = np.clip(band * 0.85 + brush * 0.15, 0, 1)
tint = hsv2rgb((x * 0.5 + y * 0.8) % 1, np.full_like(x, 0.12), np.ones_like(x))
chrome = np.clip(lum[..., None] * tint * np.array([0.93, 0.95, 1.0]), 0, 1)
Image.fromarray((chrome * 255).astype(np.uint8)).save(OUT / "chrome.webp", quality=84)

# Wrapper: crinkled metallised film. Height-field from noise -> fake lighting -> silver with pastel iridescence.
W, H = 900, 1400
hf = np.asarray(Image.fromarray((rng.random((H // 14, W // 14)) * 255).astype(np.uint8)).resize((W, H), Image.BICUBIC), float) / 255
hf += np.asarray(Image.fromarray((rng.random((H // 9, W // 9)) * 255).astype(np.uint8)).resize((W, H), Image.BICUBIC), float) / 255 * 0.25
gy, gx = np.gradient(hf)
light = np.clip(0.9 + (gx * -0.6 + gy * -0.8) * 5, 0.72, 1.12)
yy, xx = np.mgrid[0:H, 0:W]
irid = hsv2rgb(((xx / W) * 0.7 + (yy / H) * 0.5 + hf * 0.6) % 1, np.full((H, W), 0.16), np.ones((H, W)))
base = np.array([0.91, 0.895, 0.86])
film = np.clip(light[..., None] * base * (0.82 + 0.18 * irid), 0, 1)
Image.fromarray((film * 255).astype(np.uint8)).save(OUT / "wrapper.webp", quality=80)
print("ok", [p.name for p in OUT.iterdir()])
